class Solution {
public:
    int countConsistentStrings(string allowed, vector<string>& words) {
        int mask = 0;
        for (char c : allowed) {
            mask |= (1 << (c - 'a'));
        }
        int count = 0;
        for (const string& w : words) {
            bool ok = true;
            for (char c : w) {
                if (((mask >> (c - 'a')) & 1) == 0) {
                    ok = false;
                    break;
                }
            }
            if (ok) ++count;
        }
        return count;
    }
};
